	/**
	 * Default Constructor
	 */
    public BusinessUnitService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new BusinessUnitEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(BusinessUnitRepository.class) );
		this.validator		= applicationContext.getBean(BusinessUnitValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		BusinessUnit
	 */
		public BusinessUnit createBusinessUnit( CreateBusinessUnitCommand command ) {

		BusinessUnit entity = new BusinessUnit();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setBusinessUnitId( command.getBusinessUnitId() );
            entity.setName( command.getName() );
            entity.setCode( command.getCode() );
            entity.setCategory( command.getCategory() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of BusinessUnit {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateBusinessUnitCommand
	 * @return		BusinessUnit
	 */
	public BusinessUnit updateBusinessUnit( UpdateBusinessUnitCommand command ) {

		BusinessUnit entity = new BusinessUnit();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setBusinessUnitId( command.getBusinessUnitId() );
            entity.setName( command.getName() );
            entity.setCode( command.getCode() );
            entity.setEnterprise( command.getEnterprise() );
            entity.setItems( command.getItems() );
            entity.setPlants( command.getPlants() );
            entity.setCategory( command.getCategory() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of BusinessUnit {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteBusinessUnitCommand
	 */
	public void delete( DeleteBusinessUnitCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getBusinessUnitId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of BusinessUnit {0} ", id );

	}

	/**
	 * Method to retrieve the BusinessUnit via BusinessUnitFetchOneSummary
	 * @param 	summary BusinessUnitFetchOneSummary
	 * @return 	BusinessUnitFetchOneResponse
	 */
	public BusinessUnit getBusinessUnit( BusinessUnitFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "BusinessUnitFetchOneSummary arg cannot be null" );

		BusinessUnit entity = null;
		UUID id = summary.getBusinessUnitId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a BusinessUnit using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all BusinessUnits
	 *
	 * @return 	List<BusinessUnit>
	 */
    public List<BusinessUnit> getAllBusinessUnit() {
		List<BusinessUnit> list = projector.findAll( new FindAllBusinessUnitQuery() );
		return list;
	}

	/**
	 * assign Enterprise on BusinessUnit
	 * @param		command AssignEnterpriseToBusinessUnitCommand
	 */
	public void assignEnterprise( AssignEnterpriseToBusinessUnitCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignEnterprise(command.getBusinessUnitId(), command.getAssignment());

	}

	/**
	 * unAssign Enterprise on BusinessUnit
	 * @param		command UnAssignEnterpriseFromBusinessUnitCommand
	 */
	public void unAssignEnterprise( UnAssignEnterpriseFromBusinessUnitCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignEnterprise(command.getBusinessUnitId());
	}
	

